parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "Jenis_Dokumen": {
      "type": "string",
      "enum": ["Invoice", "Purchase_Order", "Remittance_Instruction", "Remittance_Advice", "Bukti_Transfer", "Unknown"],
      "description": "Kategori dokumen untuk routing ke agen spesialis yang sesuai"
    },
    "confidence_score": {
      "type": "number",
      "description": "Tingkat keyakinan AI terhadap klasifikasi ini (1-100)."
    },
    "butuh_review": {
      "type": "boolean",
      "description": "True jika dokumen buram, ambigu, tidak dikenal, atau AI ragu. False jika format sangat jelas."
    }
  },
  "required": ["Jenis_Dokumen", "confidence_score", "butuh_review"]
}
